import React, { useState } from "react";

export default function Students() {

  const [selectedStudent, setSelectedStudent] = useState(null);

  const [students, setStudents] = useState([

    {
      id: 1,
      name: "Bhagya Lakshmi",
      email: "bhagya@gmail.com",
      course: "Java Full Stack",
      progress: "85%",
      status: "Active"
    },

    {
      id: 2,
      name: "Sai Kumar",
      email: "sai@gmail.com",
      course: "React JS",
      progress: "75%",
      status: "Active"
    },

    {
      id: 3,
      name: "Priya",
      email: "priya@gmail.com",
      course: "PostgreSQL",
      progress: "92%",
      status: "Completed"
    }

  ]);


  const changeStatus = (id) => {

    const updatedStudents = students.map((student) => {

      if (student.id === id) {

        return {

          ...student,

          status:

            student.status === "Active"

              ?

              "Completed"

              :

              "Active"

        };

      }

      return student;

    });

    setStudents(updatedStudents);

  };



  return (

    <div

      style={{

        minHeight: "100vh",

        background:

          "linear-gradient(135deg,#0f172a,#1e293b,#334155)",

        padding: "40px"

      }}

    >

      <h1

        style={{

          textAlign: "center",

          color: "white",

          fontSize: "45px"

        }}

      >

        👨‍🏫 Instructor Students

      </h1>



      <p

        style={{

          textAlign: "center",

          color: "#cbd5e1",

          marginBottom: "30px"

        }}

      >

        Manage Students and Track Progress

      </p>




      <input

        type="text"

        placeholder="🔍 Search Student"

        style={{

          width: "320px",

          padding: "12px",

          borderRadius: "12px",

          border: "none",

          outline: "none",

          display: "block",

          margin: "0 auto 30px auto"

        }}

      />






      <div

        style={{

          background: "white",

          borderRadius: "25px",

          overflow: "hidden",

          boxShadow:

            "0 15px 35px rgba(0,0,0,0.25)"

        }}

      >

        <table

          style={{

            width: "100%",

            borderCollapse: "collapse"

          }}

        >

          <thead>

            <tr>

              <th style={th}>ID</th>

              <th style={th}>Student</th>

              <th style={th}>Email</th>

              <th style={th}>Course</th>

              <th style={th}>Progress</th>

              <th style={th}>Status</th>

              <th style={th}>Action</th>

            </tr>

          </thead>





          <tbody>

            {

              students.map((student) => (

                <tr key={student.id}>

                  <td style={td}>

                    {student.id}

                  </td>



                  <td style={td}>

                    {student.name}

                  </td>



                  <td style={td}>

                    {student.email}

                  </td>



                  <td style={td}>

                    {student.course}

                  </td>





                  <td style={td}>

                    <div

                      style={{

                        width: "120px",

                        background: "#e2e8f0",

                        borderRadius: "20px",

                        margin: "auto"

                      }}

                    >

                      <div

                        style={{

                          width: student.progress,

                          background: "#22c55e",

                          color: "white",

                          borderRadius: "20px",

                          padding: "5px"

                        }}

                      >

                        {student.progress}

                      </div>

                    </div>

                  </td>






                  <td style={td}>

                    <button

                      onClick={() =>

                        changeStatus(student.id)

                      }

                      style={{

                        background:

                          student.status === "Active"

                            ?

                            "linear-gradient(90deg,#22c55e,#16a34a)"

                            :

                            "linear-gradient(90deg,#3b82f6,#2563eb)",

                        color: "white",

                        border: "none",

                        padding: "10px 18px",

                        borderRadius: "25px",

                        cursor: "pointer",

                        fontWeight: "bold"

                      }}

                    >

                      {student.status}

                    </button>

                  </td>






                  <td style={td}>

                    <button

                      style={viewBtn}

                      onClick={() =>

                        setSelectedStudent(student)

                      }

                    >

                      👁 View

                    </button>

                  </td>

                </tr>

              ))

            }

          </tbody>

        </table>

      </div>






      {

        selectedStudent && (

          <div style={detailBox}>

            <h2

              style={{

                color: "#2563eb"

              }}

            >

              👨‍🎓 Student Details

            </h2>

            <hr />



            <p>

              <b>Name :</b>

              {selectedStudent.name}

            </p>



            <p>

              <b>Email :</b>

              {selectedStudent.email}

            </p>



            <p>

              <b>Course :</b>

              {selectedStudent.course}

            </p>



            <p>

              <b>Progress :</b>

              {selectedStudent.progress}

            </p>



            <p>

              <b>Status :</b>

              {selectedStudent.status}

            </p>



            <button

              style={closeBtn}

              onClick={() =>

                setSelectedStudent(null)

              }

            >

              Close

            </button>

          </div>

        )

      }

    </div>

  );

}



const th = {

  background:

    "linear-gradient(90deg,#2563eb,#7c3aed)",

  color: "white",

  padding: "18px",

  fontSize: "16px"

};



const td = {

  padding: "18px",

  textAlign: "center",

  borderBottom:

    "1px solid #e2e8f0"

};



const viewBtn = {

  background:

    "linear-gradient(90deg,#8b5cf6,#6366f1)",

  color: "white",

  border: "none",

  padding: "10px 20px",

  borderRadius: "25px",

  cursor: "pointer",

  fontWeight: "bold"

};



const closeBtn = {

  background:

    "linear-gradient(90deg,#ef4444,#dc2626)",

  color: "white",

  border: "none",

  padding: "12px 22px",

  borderRadius: "12px",

  cursor: "pointer",

  marginTop: "20px"

};



const detailBox = {

  position: "fixed",

  top: "50%",

  left: "50%",

  transform:

    "translate(-50%,-50%)",

  background: "white",

  padding: "35px",

  width: "400px",

  borderRadius: "25px",

  boxShadow:

    "0 20px 45px rgba(0,0,0,0.35)"

};
